module CounterForTestbench(
	 input clk,
	 input reset,
	 input load,
	 input up_down,
    input [3:0] data_in,
	 // frequency select, 2-bit for selecting the frequency (0.5, 1, 2 Hz)
	 input [1:0] freq_sel,
    output [3:0] count
);

wire clk_HALFHZ;
wire clk_1HZ;
wire clk_2HZ;
wire clk_Select;


	 clockDividerDFF CDTB (.clk_in(clk), .reset(reset), .clk_HALFHZ(clk_HALFHZ), .clk_1HZ(clk_1HZ), .clk_2HZ(clk_2HZ));
	 assign clk_Select = (freq_sel == 2'b00) ? clk_HALFHZ : //freq = 00, half HZ, period 2 seconds
                         (freq_sel == 2'b01) ? clk_1HZ : //freq = 01, 1HZ, period 1 second
                         (freq_sel == 2'b10) ? clk_2HZ : //freq = 10, 2HZ, period 0.5 seconds
                         clk_1HZ; //else, just make it the 1HZ clk

	 UpDownCounter UDTB (.clk(clk), .reset(reset), .load(load), .up_down(up_down), .data_in(data_in), .count(count));
endmodule








